// Persistent transport with same-ID HTTP fallback; no wallet authority in the client.
(()=>{
 let enabled=null,checking=false,socket=null,ready=false,retry=null,heartbeat=null,backoff=1000,player=null,refreshing=false,rankQueued=false;
 const pending=new Map();
 const indicator=document.createElement('small');indicator.id='liveConnection';indicator.className='live-connection';indicator.textContent='일반 연결';indicator.title='연결 상태';$('marketDescription').after(indicator);
 function mark(text,on=false){indicator.textContent=text;indicator.classList.toggle('connected',on)}
 function online(){return ready&&socket?.readyState===WebSocket.OPEN&&player===accountProfile?.id}
 function request(path,data){if(!online())return Promise.reject(Error('실시간 연결 대기'));const id=crypto.randomUUID();return new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{pending.delete(id);reject(Error('실시간 응답 시간 초과'));socket?.close()},6000);pending.set(id,{resolve,reject,timeout});try{socket.send(JSON.stringify({id,path,data}))}catch(e){clearTimeout(timeout);pending.delete(id);reject(e)}})}
 function update(data){if(!data.profile||data.playerId&&data.playerId!==accountProfile?.id)return;const revision=accountProfile?.revision;applyProfile(data.profile);if(accountProfile?.active==null&&['rocket','plinko'].includes(accountProfile?.lastSettlement?.kind))renderMarketSettlement(accountProfile.lastSettlement);if(accountProfile.revision!==revision){if(view==='camp')renderCamp();if(view==='shop')renderShop();if(view==='store')renderStore();if(view==='market'&&accountProfile.active&&accountProfile.active.kind!=='run'&&accountProfile.active.id!==(accountProfile.active.kind==='rocket'?rocket.id:plinko.id))restoreActive()}}
 async function refresh(){if(refreshing||!online()||accountBusy||pendingOperation)return;refreshing=true;try{update(await request('status',{}))}catch{}finally{refreshing=false}}
 function refreshRanking(){if(!rankQueued){rankQueued=true;setTimeout(()=>{rankQueued=false;rankingCache.clear();if($('rankModal').open&&$('rankStage'))loadRanking('rankRows',+$('rankStage').value,true,+$('rankDifficulty').value,$('rankWeapon').value);if($('clearRankRows')&&accountProfile?.lastSettlement?.outcome==='clear'){const s=accountProfile.lastSettlement;loadRanking('clearRankRows',s.stage,true,s.difficulty)}},300)}}
 function reconnect(){clearTimeout(retry);retry=setTimeout(connect,backoff+Math.random()*300);backoff=Math.min(30000,backoff*2)}
 async function connect(){if(enabled===false||checking)return;if(enabled===null){checking=true;try{const r=await fetch('/api/v3/live-config');if(!r.ok)throw Error('config');enabled=(await r.json()).enabled===true}catch{mark('일반 연결');reconnect();return}finally{checking=false}if(!enabled){mark('일반 연결');return}}if(socket||!accountReady||!accountProfile||document.hidden){reconnect();return}player=accountProfile.id;const url=new URL('/api/v3/live',location.href);url.protocol=url.protocol==='https:'?'wss:':'ws:';const ws=new WebSocket(url);socket=ws;mark('실시간 연결 중');const opening=setTimeout(()=>{if(!ready)ws.close()},7000);
 ws.onmessage=event=>{let m;try{m=JSON.parse(event.data)}catch{return}if(m.playerId!==accountProfile?.id)return;if(Number.isFinite(m.serverNow))serverOffset=m.serverNow-Date.now();if(m.type==='ready'){clearTimeout(opening);ready=true;backoff=1000;mark('실시간 연결',true);refresh();heartbeat=setInterval(()=>{if(!online())return;refresh();if($('rankModal').open)refreshRanking()},10000)}else if(m.type==='response'){const item=pending.get(m.id);if(!item)return;clearTimeout(item.timeout);pending.delete(m.id);if(m.status>=400)item.reject(Object.assign(Error(m.error||'서버 오류'),{status:m.status}));else item.resolve(m)}else if(m.type==='profile')update(m);else if(m.type==='invalidate'){if(m.account)refresh();if(m.rank){refreshRanking();refreshLiveTitles()}}};
 ws.onclose=()=>{clearTimeout(opening);if(socket!==ws)return;ready=false;socket=null;clearInterval(heartbeat);mark('일반 연결 · 재연결 중');for(const item of pending.values()){clearTimeout(item.timeout);item.reject(Error('실시간 연결 끊김'))}pending.clear();scheduleMarketPoll();reconnect()};ws.onerror=()=>ws.close()}
 window.realtimeReady=online;window.realtimeRequest=request;window.realtimeReset=()=>{ready=false;socket?.close()};
 window.addEventListener('online',()=>{clearTimeout(retry);connect()});window.addEventListener('pagehide',()=>{ready=false;socket?.close()});document.addEventListener('visibilitychange',()=>{if(!document.hidden){clearTimeout(retry);if(online())refresh();else connect()}});retry=setTimeout(connect,500);
})();
